function [tq] = ring_pump_max(tq_stated, hmax, tsd)
%RING_PUMP_MAX  The pump's largest torque [N m]: a designed pump's stated torque when it states one (finite and positive), else
%   twice the capacity over the spin-down time.
%   tq_stated: real[1] (passed a plain number)
%   hmax: real[1] (passed a plain number)
%   tsd: real[1] (passed a plain number)
%   returns tq: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    tq = 0;
    tq = asils.pc.choose((isfinite(tq_stated) && (tq_stated > 0)), tq_stated, ((2 * hmax) / tsd));
end
